const T=" GRUIDNEABFHJMPSO123456789TV";
const map=c=>{
  if(c>=0x20&&c<=0x3B) return T[c-0x20];
  if(c===0x1B||c===0x1C) return "Y";
  if(c===0x3C) return "@";
  if(c===0x3D) return "(";
  if(c===0x3E) return "L";
  if(c===0x3F) return "|";
  if(c===0x00) return "+";
  if(c===0xEA) return "~";
  return ".";
};
const lines=[]; let cur="";
for(const b of bytes){ cur+=map(b); if(cur.length>=32){lines.push(cur);cur="";} }
if(cur) lines.push(cur);
return {kind:"text",lines};

